<script setup lang="ts">
import {computed,ref} from "vue";import {Copy,Plus,ShieldCheck} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import ZButton from "@/components/zs/ZButton.vue";import PageHeader from "@/components/zs/PageHeader.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import SidePanel from "@/components/zs/SidePanel.vue";import Field from "@/components/zs/Field.vue";import ValidationMessage from "@/components/zs/ValidationMessage.vue";import {useAsyncData,useMutation} from "@/composables/useAsyncData";import {platformRepository} from "@/services/platform/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {PlatformRole} from "@/types/platform";
setPageMeta("Roles & Permissions","Role definitions and effective company permissions.");const company=useCompanyStore(),state=useAsyncData(()=>platformRepository.roles(company.activeCompanyId),{watch:[()=>company.activeCompanyId]}),open=ref(false),editing=ref<PlatformRole|null>(null),name=ref(''),selected=ref<number[]>([]);const roles=computed(()=>state.data.value?.roles??[]),permissions=computed(()=>state.data.value?.permissions??[]);const columns:Column[]=[{key:'name',header:'Role'},{key:'users',header:'Users',align:'right'},{key:'permissions',header:'Permissions'},{key:'actions',header:''}];const save=useMutation(()=>editing.value?platformRepository.updateRole(company.activeCompanyId,editing.value.id,{name:name.value,permission_ids:selected.value}):platformRepository.createRole(company.activeCompanyId,{name:name.value,permission_ids:selected.value}));function edit(role?:PlatformRole){editing.value=role??null;name.value=role?.name??'';selected.value=role?.permissions.map(x=>x.id)??[];open.value=true}async function submit(){if(!await save.run())return;showToast(editing.value?'Role updated':'Role created');open.value=false;await state.refresh()}async function clone(role:PlatformRole){await platformRepository.cloneRole(company.activeCompanyId,role.id,`${role.name} Copy`);showToast('Role cloned');await state.refresh()}async function archive(role:PlatformRole){await platformRepository.archiveRole(company.activeCompanyId,role.id);showToast('Role archived');await state.refresh()}
</script>
<template><AppShell><PageHeader title="Roles & Permissions" description="Company-scoped access enforced by the authoritative backend"><template #actions><ZButton v-if="company.hasPermission('platform.roles.manage')" @click="edit()"><Plus class="size-4"/>New role</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Roles" :value="String(roles.length)" tone="brand"/><StatCard label="Users assigned" :value="String(roles.reduce((sum,r)=>sum+(r.memberships_count??0),0))"/><StatCard label="Permissions" :value="String(permissions.length)" tone="success"/></div><ValidationMessage :message="state.error.value?.message"/><Panel title="Roles"><DataTable :columns="columns" :rows="roles" :min-width="940"><template #name="{row}:{row:PlatformRole}"><span class="inline-flex items-center gap-2 font-medium text-content"><ShieldCheck class="size-3.5 text-content-muted"/>{{row.name}}<span v-if="row.is_system" class="zs-badge badge-warning">System</span><span v-if="row.archived_at" class="zs-badge badge-neutral">Archived</span></span></template><template #users="{row}">{{row.memberships_count??0}}</template><template #permissions="{row}:{row:PlatformRole}"><div class="flex max-w-xl flex-wrap gap-1"><span v-for="permission in row.permissions.slice(0,8)" :key="permission.id" class="num zs-badge badge-neutral">{{permission.name}}</span><span v-if="row.permissions.length>8" class="zs-badge badge-neutral">+{{row.permissions.length-8}}</span></div></template><template #actions="{row}:{row:PlatformRole}"><div v-if="company.hasPermission('platform.roles.manage')" class="flex justify-end gap-1"><ZButton variant="ghost" :disabled="row.is_system" @click="edit(row)">Edit</ZButton><ZButton variant="ghost" @click="clone(row)"><Copy class="size-3.5"/>Clone</ZButton><ZButton variant="ghost" :disabled="row.is_system||!!row.archived_at" @click="archive(row)">Archive</ZButton></div></template></DataTable></Panel><SidePanel :open="open" :title="editing?'Edit role':'Create role'" description="You can only grant permissions held by your own role." @close="open=false"><form class="space-y-4" @submit.prevent="submit"><Field v-model="name" label="Role name" required/><div><p class="label-caps">Permissions</p><div class="mt-2 max-h-[28rem] space-y-2 overflow-y-auto rounded-md border border-line p-3"><label v-for="permission in permissions" :key="permission.id" class="flex items-start gap-2 text-xs text-content-secondary"><input v-model="selected" type="checkbox" :value="permission.id" class="mt-0.5 accent-[var(--primary)]"/><span><span class="font-medium text-content">{{permission.name}}</span><span v-if="permission.description" class="block text-content-muted">{{permission.description}}</span></span></label></div></div><ValidationMessage :message="save.error.value?.message"/><ZButton type="submit" :disabled="save.saving.value">{{save.saving.value?'Saving…':'Save role'}}</ZButton></form></SidePanel></AppShell></template>
